<?php ui_header('Quản trị nội dung','Xem xét báo cáo vi phạm và yêu cầu khôi phục tài khoản.'); ?><section class="panel section"><h2>Đồng bộ việc làm</h2><form data-api="/external-jobs/crawl"><label>Từ khóa (dấu phẩy)<input name="keywords" data-array value="developer"></label><button>Đồng bộ</button></form></section><h2>Báo cáo vi phạm</h2><?php foreach($data as $report): ?><article class="panel section"><strong><?= e($report['targetType']) ?> · <?= e($report['status']) ?></strong><p><?= e($report['reason']) ?></p><p><?= e($report['details']??'') ?></p><button data-action="/moderation/reports/<?= e($report['id']) ?>" data-method="PATCH" data-body='{"action":"KEEP"}' data-reload>Giữ nội dung</button><button class="ghost" data-action="/moderation/reports/<?= e($report['id']) ?>" data-method="PATCH" data-body='{"action":"DELETE"}' data-reload>Xóa nội dung</button></article><?php endforeach; ?><h2>Yêu cầu khôi phục tài khoản</h2><?php foreach($recoveries as $recovery): ?><article class="panel section"><p><?= e($recovery['email']??$recovery['phone']??'') ?> · <?= e($recovery['status']) ?></p><button data-action="/moderation/recovery-requests/<?= e($recovery['id']) ?>" data-method="PATCH" data-reload>Đã xử lý</button></article><?php endforeach; ?>
